gcd:
module gcd version 3
export c fn solve(data:slice<i64>, key:i64) -> i64:
    if len(data) < 2:
        return 0
    a = data[0]
    b = data[1]
    if a < 0:
        a = -a
    if b < 0:
        b = -b
    while b != 0:
        r = a % b
        a = b
        b = r
    return a

