binary_search:
module binary_search version 3
export c fn solve(data:slice<i64>, key:i64) -> i64:
    lo = 0
    hi = len(data)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if data[mid] < key:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(data) and data[lo] == key:
        return lo
    return -1

