export c fn solve(data:slice<i64>, key:i64) -> i64:
    for i in range(len(data) // 2):
        j = len(data) - 1 - i
        x = data[i]
        data[i] = data[j]
        data[j] = x
    return len(data)

sort:
module sort version 3
export c fn solve(data:slice<i64>, key:i64) -> i64:
    for i in range(1, len(data)):
        x = data[i]
        j = i
        while j > 0 and data[j - 1] > x:
            data[j] = data[j - 1]
            j -= 1
        data[j] = x
    return len(data)
